def examples_for(topic: str | None) -> list[tuple[str, str]]:
    """คืน [(ชื่อสถานการณ์, ประโยคตัวอย่าง)] ของหัวข้อนั้น"""
    return [(title, text) for t, title, text in SCENARIOS if t == topic]


# ชื่อภาษาไทยของหัวข้อที่ไม่มีในตาราง SCENARIOS (ใช้บอก Gemini ว่าเรื่องนี้คือหัวข้ออะไร)
EXTRA_TOPIC_TITLES = {
    "sleep": "นอนไม่หลับ",
    "anxiety": "ความวิตกกังวล",
    "self_worth": "รู้สึกไร้ค่า/ไม่ดีพอ",
    "exam_fail": "สอบตกหรือผิดหวังกับผลการเรียน",
    "anger": "ความโกรธ คุมอารมณ์ไม่ได้",
    "guilt_shame": "ความรู้สึกผิดหรืออับอาย",
    "finance": "ปัญหาการเงินทั่วไป",
    "health_body": "สุขภาพกายและการเจ็บป่วย",
}


def title_for(topic: str | None) -> str:
    """ชื่อภาษาไทยของหัวข้อ (ถ้าจับหัวข้อไม่ได้ คืน 'เรื่องทั่วไป')"""
    if not topic:
        return "เรื่องทั่วไป (ระบบจับหัวข้อไม่ได้)"
    for t, title, _ in SCENARIOS:
        if t == topic:
            return title
    return EXTRA_TOPIC_TITLES.get(topic, topic)
